{
    touchgfx::CanvasWidgetRenderer::resetBuffer();
}

void Screen15ViewBase::setupScreen()
{
    topStatusBar15.initialize();
}

void Screen15ViewBase::flexButtonCallbackHandler(const touchgfx::AbstractButtonContainer& src)
{
    if (&src == &buttonBattery)
    {
        //Interaction1
        //When buttonBattery clicked call virtual function
        //Call buttonBatteryClicked
        buttonBatteryClicked();
    }
    if (&src == &buttongoback)
    {
        //Interaction2
        //When buttongoback clicked call virtual function
        //Call buttongobackClicked
        buttongobackClicked();
    }
    if (&src == &buttonend)
    {
        //Interaction3
        //When buttonend clicked call virtual function
        //Call endProcedureClicked
        endProcedureClicked();
    }
    if (&src == &dummybotton)
    {
        //Interaction4
        //When dummybotton clicked change screen to Screen16
        //Go to Screen16 with no screen transition
        application().gotoScreen16ScreenNoTransition();
    }
    if (&src == &btnMainClose)
    {
        //Interaction5
        //When btnMainClose clicked hide containerAlarm
        //Hide containerAlarm
        containerAlarm.setVisible(false);
        containerAlarm.invalidate();
    }
    if (&src == &btnAlertTrigger)
    {
        //Interaction6
        //When btnAlertTrigger clicked show containerAlarm
        //Show containerAlarm
        containerAlarm.setVisible(true);
        containerAlarm.invalidate();
    }
    if (&src == &btnAcknowledgeCritical)
    {
        //Interaction7
        //When btnAcknowledgeCritical clicked hide containerCritical
        //Hide containerCritical
        containerCritical.setVisible(false);
        containerCritical.invalidate();
    }
}
